using AltF4.Cinema.Core;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace AltF4.Cinema.Tests;

public sealed class BusinessTests : IDisposable
{
    readonly string path=Path.Combine(Path.GetTempPath(),$"altf4-test-{Guid.NewGuid():N}.db");
    CinemaDb Db()=>new(path);Func<CinemaDb> Factory=>Db;
    readonly Actor admin;readonly Actor cashier;
    public BusinessTests(){Bootstrap.Initialize(Factory,true);var security=new SecurityService(Factory);admin=security.Login("admin",Bootstrap.DemoPassword);cashier=security.Login("cashier",Bootstrap.DemoPassword);}
    public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var p in new[]{path,path+"-wal",path+"-shm"})if(File.Exists(p))File.Delete(p);}
    SaleRequest Request(bool vip=false,string promo=""){using var db=Db();var show=db.Showtimes.First();return new(show.Id,[db.Seats.First(s=>s.RoomId==show.RoomId).Id],[new(db.Products.First().Id,2)],vip?db.Customers.Single(c=>c.Vip).Id:null,promo,1000000);}
    [Fact] public void PasswordsAreSaltedAndVerified(){var a=Passwords.Hash("StrongPass123");var b=Passwords.Hash("StrongPass123");Assert.NotEqual(a,b);Assert.True(Passwords.Verify("StrongPass123",a));Assert.False(Passwords.Verify("wrong",a));Assert.False(Passwords.Verify("x","broken"));Assert.Throws<InvalidOperationException>(()=>Passwords.Hash("123"));}
    [Fact] public void LoginLocksAfterFiveFailures(){var sec=new SecurityService(Factory);for(int i=0;i<5;i++)Assert.Throws<InvalidOperationException>(()=>sec.Login("cashier","wrong"));Assert.Throws<InvalidOperationException>(()=>sec.Login("cashier",Bootstrap.DemoPassword));}
    [Fact] public void CheckoutUpdatesSeatsStockPointsAndUsesHigherDiscount(){var req=Request(true,"ALTF4");using var before=Db();var stock=before.Products.First().Stock;var result=new BusinessService(Factory).Checkout(cashier,req);using var after=Db();Assert.Equal(15,result.DiscountPercent);Assert.Equal(result.Subtotal*15/100,result.Discount);Assert.Equal(stock-2,after.Products.First().Stock);Assert.Single(after.Reservations);Assert.Equal(result.Total/10000,after.Customers.Single(c=>c.Vip).Points);}
    [Fact] public void SameSeatCannotBeSoldTwice(){var b=new BusinessService(Factory);var req=Request();b.Checkout(cashier,req);Assert.Throws<InvalidOperationException>(()=>b.Checkout(cashier,req));using var db=Db();Assert.Single(db.Sales);Assert.Single(db.Reservations);}
    [Fact] public void UniqueIndexProtectsReservationEvenOutsideService(){var b=new BusinessService(Factory);var sale=b.Checkout(cashier,Request());using var db=Db();var first=db.Reservations.Single();db.Reservations.Add(new(){ShowtimeId=first.ShowtimeId,SeatId=first.SeatId,SaleId=sale.Id});Assert.Throws<DbUpdateException>(()=>db.SaveChanges());}
    [Fact] public void FaultAfterSavingInvoiceRollsBackEverything(){var req=Request(true);using var before=Db();var stock=before.Products.First().Stock;Assert.Throws<IOException>(()=>new BusinessService(Factory).Checkout(cashier,req,()=>throw new IOException("Injected failure")));using var after=Db();Assert.Empty(after.Sales);Assert.Empty(after.SaleLines);Assert.Empty(after.Reservations);Assert.Equal(stock,after.Products.First().Stock);Assert.Equal(0,after.Customers.Single(c=>c.Vip).Points);}
    [Fact] public void InsufficientStockRejectsEntireOrder(){var req=Request();req=req with{Products=[new(req.Products[0].ProductId,100)]};Assert.Throws<InvalidOperationException>(()=>new BusinessService(Factory).Checkout(cashier,req));using var db=Db();Assert.Empty(db.Sales);}
    [Fact] public void InvalidPromoAndUnderpaymentAreRejected(){var b=new BusinessService(Factory);Assert.Throws<InvalidOperationException>(()=>b.Checkout(cashier,Request(false,"EXPIRED")));Assert.Throws<InvalidOperationException>(()=>b.Checkout(cashier,Request() with{CashReceived=1}));using var db=Db();Assert.Empty(db.Sales);}
    [Fact] public void RefundRestoresStockAndSeatExactlyOnce(){var b=new BusinessService(Factory);var req=Request(true);using var before=Db();var stock=before.Products.First().Stock;var sale=b.Checkout(cashier,req);b.Refund(admin,sale.Id,"Khách đổi kế hoạch");Assert.Throws<InvalidOperationException>(()=>b.Refund(admin,sale.Id,"Hoàn lần hai"));using var db=Db();Assert.Equal(stock,db.Products.First().Stock);Assert.Empty(db.Reservations);Assert.Equal(0,db.Customers.Single(c=>c.Vip).Points);Assert.Equal("Refunded",db.Sales.Single().Status);Assert.Equal(0,b.Revenue(admin,DateTime.Today,DateTime.Today.AddDays(1)).Sum(x=>x.Amount));}
    [Fact] public void CashierCannotCallAdminOrRefundServices(){var b=new BusinessService(Factory);Assert.Throws<UnauthorizedAccessException>(()=>new CatalogService(Factory).Save(cashier,new Role{Name="Hack",Permissions=Access.All}));Assert.Throws<UnauthorizedAccessException>(()=>b.Refund(cashier,1,"Không có quyền"));Assert.Throws<UnauthorizedAccessException>(()=>b.Revenue(cashier,DateTime.Today,DateTime.Today.AddDays(1)));Assert.Throws<UnauthorizedAccessException>(()=>b.Receive(cashier,1,1,1,100));}
    [Fact] public void ScheduleRejectsOverlapAndCleanupViolation(){using var db=Db();var old=db.Showtimes.First();var cat=new CatalogService(Factory);Assert.Throws<InvalidOperationException>(()=>cat.Save(admin,new Showtime{MovieId=old.MovieId,RoomId=old.RoomId,StartsAt=old.EndsAt.AddMinutes(10),BasePrice=75000}));}
    [Fact] public void LastAdministratorCannotBeRemoved(){using var db=Db();var u=db.Users.Single(x=>x.Username=="admin");u.Active=false;Assert.Throws<InvalidOperationException>(()=>new CatalogService(Factory).Save(admin,u));var r=db.Roles.Single(x=>x.Permissions==Access.All);r.Permissions=Access.Sell;Assert.Throws<InvalidOperationException>(()=>new CatalogService(Factory).Save(admin,r));}
    [Fact] public void StockCannotBeEditedThroughCatalog(){using var db=Db();var p=db.Products.First();var stock=p.Stock;p.Stock=999;new CatalogService(Factory).Save(admin,p);using var after=Db();Assert.Equal(stock,after.Products.First().Stock);}
    [Fact] public void InventoryReceiptAndStockAreCommittedTogether(){using var db=Db();var p=db.Products.First();new BusinessService(Factory).Receive(admin,p.Id,db.Suppliers.First().Id,10,20000);using var after=Db();Assert.Equal(p.Stock+10,after.Products.First().Stock);Assert.Single(after.InventoryReceipts);}
    [Fact] public void PasswordResetRequiresChangeAndRevokesServiceAccess(){using var db=Db();var u=db.Users.Single(x=>x.Username=="cashier");new CatalogService(Factory).Save(admin,u,"ResetPassword123");var sec=new SecurityService(Factory);var actor=sec.Login("cashier","ResetPassword123");Assert.True(sec.MustChange(actor));Assert.Throws<UnauthorizedAccessException>(()=>new BusinessService(Factory).Checkout(actor,Request()));sec.ChangePassword(actor,"ResetPassword123","NewPassword456");Assert.False(sec.MustChange(actor));}
    [Fact] public void RevenueUsesRefundDateRatherThanErasingOriginalIncome(){var b=new BusinessService(Factory);var sale=b.Checkout(cashier,Request());using(var db=Db()){var row=db.Sales.Find(sale.Id)!;row.CreatedAt=DateTime.Today.AddDays(-1).AddHours(12);db.SaveChanges();}b.Refund(admin,sale.Id,"Khách thay đổi lịch");Assert.Equal(sale.Total,b.Revenue(admin,DateTime.Today.AddDays(-1),DateTime.Today).Sum(x=>x.Amount));Assert.Equal(-sale.Total,b.Revenue(admin,DateTime.Today,DateTime.Today.AddDays(1)).Sum(x=>x.Amount));}
    [Fact] public async Task ConcurrentCheckoutHasOnlyOneWinner(){var req=Request();async Task<bool> Attempt(){return await Task.Run(()=>{try{new BusinessService(Factory).Checkout(cashier,req);return true;}catch{return false;}});}var outcomes=await Task.WhenAll(Attempt(),Attempt());Assert.Single(outcomes,x=>x);using var db=Db();Assert.Single(db.Sales);Assert.Single(db.Reservations);Assert.Equal(78,db.Products.First().Stock);}
    [Fact] public void RefundAfterShowStartsIsRejected(){var b=new BusinessService(Factory);var sale=b.Checkout(cashier,Request());using(var db=Db()){var show=db.Showtimes.Find(sale.Lines.First(l=>l.ShowtimeId!=null).ShowtimeId)!;show.StartsAt=DateTime.Now.AddMinutes(-1);db.SaveChanges();}Assert.Throws<InvalidOperationException>(()=>b.Refund(admin,sale.Id,"Khách muốn hoàn vé"));}
    [Fact] public void WrongRoomSeatAndDuplicateSeatAreRejected(){using var db=Db();var req=Request();var room=db.Showtimes.Find(req.ShowtimeId)!.RoomId;var wrong=db.Seats.First(s=>s.RoomId!=room).Id;var b=new BusinessService(Factory);Assert.Throws<InvalidOperationException>(()=>b.Checkout(cashier,req with{SeatIds=[wrong]}));Assert.Throws<InvalidOperationException>(()=>b.Checkout(cashier,req with{SeatIds=[req.SeatIds[0],req.SeatIds[0]]}));}
    [Fact] public void RevokingRoleTakesEffectForExistingActor(){using(var db=Db()){db.Roles.Single(r=>r.Name=="Thu ngân").Permissions=Access.None;db.SaveChanges();}Assert.Throws<UnauthorizedAccessException>(()=>new BusinessService(Factory).Checkout(cashier,Request()));}
    [Fact] public void VipWithoutPromoGetsTenPercent(){var sale=new BusinessService(Factory).Checkout(cashier,Request(true));Assert.Equal(10,sale.DiscountPercent);Assert.Equal(sale.Subtotal-sale.Subtotal/10,sale.Total);}
    [Fact] public void RevenueIncludesTheEntireSelectedLastDay(){var b=new BusinessService(Factory);var sale=b.Checkout(cashier,Request());using(var db=Db()){db.Sales.Find(sale.Id)!.CreatedAt=DateTime.Today.AddHours(23).AddMinutes(59);db.SaveChanges();}Assert.Equal(sale.Total,b.Revenue(admin,DateTime.Today,DateTime.Today.AddDays(1)).Sum(x=>x.Amount));Assert.Empty(b.Revenue(admin,DateTime.Today.AddDays(-1),DateTime.Today));}
}
